// What the browser needs from the API reference: one explanation per Reactive CSS token, and the
// library version. Generated by scripts/sync-runtime.mjs from the same entries as GLOSSARY in
// reference.ts (tests/unit/glossary.test.ts), so client islands do not ship the reference prose.
import glossary from '~/generated/glossary.json';
import runtime from '~/generated/runtime.json';

export interface GlossaryItem { label: string; kind: string; summary: string; href: string }
export const GLOSSARY = glossary as Record<string, GlossaryItem>;
export const LIBRARY_VERSION = runtime.registry;
